{
  "facts": [
    {
      "topic": "target_route",
      "statement": "The entry compresses with ZSTD_compressStream2, decompresses with ZSTD_decompressStream, then checks the decoded size and bytes. It also performs in-place decompression with ZSTD_decompressDCtx and repeats the size and byte checks.",
      "evidence": [
        {
          "unit_id": "u-9dc9e88ae722c8cbe085",
          "start_line": 59,
          "end_line": 153,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-9dc9e88ae722c8cbe085",
          "start_line": 185,
          "end_line": 208,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "contract",
      "statement": "ZSTD_CCtx_loadDictionary accepts dictionary bytes in the context's initialization stage, copies them, and records their size. ZSTD_CCtx_refCDict is another initialization-stage route. ZSTD_compressStream2 initializes a local dictionary or uses a referenced CDict before beginning buffered compression.",
      "evidence": [
        {
          "unit_id": "u-b5697ee0104bd691ea91",
          "start_line": 1270,
          "end_line": 1323,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-b5697ee0104bd691ea91",
          "start_line": 6175,
          "end_line": 6201,
          "role": "dependency",
          "dependency_reason": "Streaming initialization turns a loaded dictionary into a local CDict or uses a referenced CDict."
        },
        {
          "unit_id": "u-b5697ee0104bd691ea91",
          "start_line": 6246,
          "end_line": 6252,
          "role": "dependency",
          "dependency_reason": "The single-thread streaming path passes that dictionary state into compression initialization."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "target_route",
      "statement": "Compression initialization passes dictionary content through ZSTD_compress_insertDictionary; raw-content and automatically detected raw dictionaries reach ZSTD_loadDictionaryContent. The block path derives a dictionary mode from match state and selects a compressor for that mode.",
      "evidence": [
        {
          "unit_id": "u-b5697ee0104bd691ea91",
          "start_line": 5069,
          "end_line": 5115,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-b5697ee0104bd691ea91",
          "start_line": 5025,
          "end_line": 5064,
          "role": "dependency",
          "dependency_reason": "Dictionary insertion calls the content loader for supported raw-content routes."
        },
        {
          "unit_id": "u-b5697ee0104bd691ea91",
          "start_line": 3235,
          "end_line": 3236,
          "role": "dependency",
          "dependency_reason": "Block compression obtains its dictionary mode from the initialized match state."
        },
        {
          "unit_id": "u-b5697ee0104bd691ea91",
          "start_line": 3335,
          "end_line": 3355,
          "role": "dependency",
          "dependency_reason": "The block path passes that mode to compressor selection, including the normal path without a sequence producer."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "contract",
      "statement": "The after-source selector has distinct no-dictionary, external-dictionary, dictionary-match-state, and dedicated-dictionary-search compressor entries. Dictionary-aware selection is therefore a supported source behavior, subject to obtaining dictionary state.",
      "evidence": [
        {
          "unit_id": "u-b5697ee0104bd691ea91",
          "start_line": 3032,
          "end_line": 3115,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "alternative",
      "statement": "The source retains two compression setup routes relevant to the tuple: loading dictionary bytes and referencing a CDict. A session-only CCtx reset does not call ZSTD_clearAllDicts; clearing occurs when parameters are reset.",
      "evidence": [
        {
          "unit_id": "u-b5697ee0104bd691ea91",
          "start_line": 1308,
          "end_line": 1323,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-b5697ee0104bd691ea91",
          "start_line": 1354,
          "end_line": 1369,
          "role": "dependency",
          "dependency_reason": "The reset implementation distinguishes session-only reset from the parameter reset that clears dictionaries."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "counterevidence",
      "statement": "The separate dictionary_stream_round_trip target loads dictionary bytes or references a prefix before its ZSTD_compressStream2 calls. This demonstrates a streaming setup route, but it is a different entry point and does not make the frozen target reach that route.",
      "evidence": [
        {
          "unit_id": "u-dbcb07b3bcd3a1a65db0",
          "start_line": 59,
          "end_line": 79,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-dbcb07b3bcd3a1a65db0",
          "start_line": 81,
          "end_line": 102,
          "role": "dependency",
          "dependency_reason": "The separate target subsequently invokes the streaming compression operation."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "scope",
      "statement": "The frozen entry and its complete random-parameter helper contain no dictionary load, CDict reference, or decompression-dictionary setup call. Fuzzer bytes are divided between parameter generation and source data, so those bytes cannot select such a setup through the calls shown in this target.",
      "evidence": [
        {
          "unit_id": "u-9dc9e88ae722c8cbe085",
          "start_line": 1,
          "end_line": 218,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-194debf8ea4cd55b47ba",
          "start_line": 1,
          "end_line": 207,
          "role": "dependency",
          "dependency_reason": "The complete helper sets compression parameters, registers or clears a sequence producer, and separately defines dictionary training; the entry calls only its parameter setter."
        }
      ],
      "absence_claim": true,
      "audited_unit_ids": [
        "u-9dc9e88ae722c8cbe085",
        "u-194debf8ea4cd55b47ba"
      ]
    },
    {
      "topic": "counterevidence",
      "statement": "The helper does vary dictionary-related parameters, including dictIDFlag, dedicated dictionary search, dictionary attachment preference, and CDict prefetch. Those parameter settings do not themselves supply dictionary content to either context.",
      "evidence": [
        {
          "unit_id": "u-194debf8ea4cd55b47ba",
          "start_line": 101,
          "end_line": 165,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-b5697ee0104bd691ea91",
          "start_line": 1270,
          "end_line": 1323,
          "role": "dependency",
          "dependency_reason": "The source supplies dictionary content through separate context setup functions."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "contract",
      "statement": "ZSTD_decompressStream obtains a DDict from the decompression context for either its single-pass shortcut or its streaming frame initialization. It does not derive dictionary content from the compressed frame alone in those paths.",
      "evidence": [
        {
          "unit_id": "u-d432cbad62b16480e910",
          "start_line": 2165,
          "end_line": 2173,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-d432cbad62b16480e910",
          "start_line": 2192,
          "end_line": 2203,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "consequence",
      "statement": "For the frozen entry, dictionary-backed compression cannot be reached through its current setup: it creates the CCtx, resets only its session, varies parameters, and calls ZSTD_compressStream2 without loading or referencing a dictionary. Its existing checks concern errors, decoded size, and byte equality; they do not assert dictionary coverage.",
      "evidence": [
        {
          "unit_id": "u-9dc9e88ae722c8cbe085",
          "start_line": 59,
          "end_line": 67,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-9dc9e88ae722c8cbe085",
          "start_line": 156,
          "end_line": 205,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-b5697ee0104bd691ea91",
          "start_line": 6175,
          "end_line": 6201,
          "role": "dependency",
          "dependency_reason": "Streaming initialization uses dictionary state already configured on the CCtx."
        },
        {
          "unit_id": "u-a7cd9e43defd8d40468a",
          "start_line": 40,
          "end_line": 47,
          "role": "dependency",
          "dependency_reason": "These macros make the entry's existing checks abort on failed conditions or zstd errors."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    }
  ],
  "missing_information": [
    "The source contract for ZSTD_DCtx_loadDictionary or ZSTD_DCtx_refDDict, including how that setup is retained for both ZSTD_decompressStream and the entry's later ZSTD_decompressDCtx call."
  ],
  "requested_symbols": [
    "ZSTD_DCtx_loadDictionary",
    "ZSTD_DCtx_refDDict",
    "ZSTD_getDDict",
    "ZSTD_decompressDCtx"
  ],
  "requested_paths": [
    "lib/decompress/zstd_decompress.c"
  ]
}
